  private setupTouchControls() {
    // Left Screen Joystick Base & Thumb
    this.joystickBase = this.scene.add.graphics();
    this.joystickBase.fillStyle(0xffffff, 0.15);
    this.joystickBase.fillCircle(this.joystickOriginX, this.joystickOriginY, 65);
    this.joystickBase.lineStyle(3, 0xfacc15, 0.4);
    this.joystickBase.strokeCircle(this.joystickOriginX, this.joystickOriginY, 65);
    this.container.add(this.joystickBase);

    this.joystickThumb = this.scene.add.graphics();
    this.joystickThumb.fillStyle(0xfacc15, 0.6);
    this.joystickThumb.fillCircle(this.joystickOriginX, this.joystickOriginY, 28);
    this.container.add(this.joystickThumb);

    // Touch events for Virtual Joystick
    this.scene.input.on('pointerdown', (pointer: Phaser.Input.Pointer) => {
      if (pointer.x < 500 && pointer.y > 200 && this.joystickPointerId === null) {
        this.joystickPointerId = pointer.id;
        this.updateJoystick(pointer.x, pointer.y);
      }
    });

    this.scene.input.on('pointermove', (pointer: Phaser.Input.Pointer) => {
      if (pointer.id === this.joystickPointerId) {
        this.updateJoystick(pointer.x, pointer.y);
      }
    });

    this.scene.input.on('pointerup', (pointer: Phaser.Input.Pointer) => {
      if (pointer.id === this.joystickPointerId) {
        this.joystickPointerId = null;
        this.touchState.vx = 0;
        this.touchState.vy = 0;
        this.resetJoystick();
      }
    });
  }

  private updateJoystick(px: number, py: number) {
    const dx = px - this.joystickOriginX;
    const dy = py - this.joystickOriginY;
    const dist = Math.hypot(dx, dy);
    const maxDist = 60;

    const clampDist = Math.min(dist, maxDist);
    const angle = Math.atan2(dy, dx);

    const thumbX = this.joystickOriginX + Math.cos(angle) * clampDist;
    const thumbY = this.joystickOriginY + Math.sin(angle) * clampDist;

    this.joystickThumb.clear();
    this.joystickThumb.fillStyle(0xfacc15, 0.8);
    this.joystickThumb.fillCircle(thumbX, thumbY, 28);

    if (dist > 10) {
      this.touchState.vx = Math.cos(angle);
      this.touchState.vy = Math.sin(angle);
    } else {
      this.touchState.vx = 0;
      this.touchState.vy = 0;
    }
  }

  private resetJoystick() {
    this.joystickThumb.clear();
    this.joystickThumb.fillStyle(0xfacc15, 0.6);
    this.joystickThumb.fillCircle(this.joystickOriginX, this.joystickOriginY, 28);
  }

