  update(time: number, delta: number) {
    if (this.dialogueModal.isActive || this.shopModal.isActive) return;

    // Movement Input
    let vx = 0;
    let vy = 0;

    // Keyboard Input
    if (this.cursors) {
      if (this.cursors.left.isDown || this.wasdKeys.A.isDown) vx -= 1;
      if (this.cursors.right.isDown || this.wasdKeys.D.isDown) vx += 1;
      if (this.cursors.up.isDown || this.wasdKeys.W.isDown) vy -= 1;
      if (this.cursors.down.isDown || this.wasdKeys.S.isDown) vy += 1;
    }

    // Touch Virtual Joystick Input
    if (this.hudOverlay.touchState.vx !== 0 || this.hudOverlay.touchState.vy !== 0) {
      vx = this.hudOverlay.touchState.vx;
      vy = this.hudOverlay.touchState.vy;
    }

    // Normalize diagonal velocity
    if (vx !== 0 && vy !== 0) {
      const len = Math.hypot(vx, vy);
      vx /= len;
      vy /= len;
    }

    // Update Player
    this.player.update(delta, vx, vy);

    // Render Dropped Lure Items
    this.renderDroppedItems();

    // Update Hubris AI
    let distToHubris = 9999;
    if (this.hubris) {
      this.hubris.update(delta, this.player, this.droppedItems, this.roomWalls);
      distToHubris = Phaser.Math.Distance.Between(this.player.x, this.player.y, this.hubris.x, this.hubris.y);

      // Check Hubris Catching Player Collision
      if (!this.player.isHidden && distToHubris < 30) {
        this.handleCaughtByHubris();
        return;
      }
    }

    // Update Bunny Guards
    this.bunnyGuards.forEach(guard => {
      guard.update(delta, this.player, this.droppedItems, this.roomWalls);
      const d = Phaser.Math.Distance.Between(this.player.x, this.player.y, guard.x, guard.y);
      if (!this.player.isHidden && d < 28) {
        this.handleCaughtByHubris();
      }
    });

    // Update Proximity Bell Jingle HUD
    const isChasing = (this.hubris && this.hubris.currentState === 'CHASE') || this.bunnyGuards.some(g => g.currentState === 'CHASE');
    this.hudOverlay.updateBellProximity(distToHubris, isChasing);
  }

