public handleInteractOrHide() {
    if (this.dialogueModal.isActive || this.shopModal.isActive) return;

    // 1. If currently hidden, unhide!
    if (this.player.isHidden) {
      this.player.unhide();
      audio.playClick();
      return;
    }

    const playerBounds = new Phaser.Geom.Rectangle(this.player.x - 20, this.player.y - 20, 40, 40);

    // 2. Check overlap with Hiding Spots
    for (const spot of this.hidingZones) {
      const spotBounds = new Phaser.Geom.Rectangle(
        spot.zone.x - spot.zone.width / 2,
        spot.zone.y - spot.zone.height / 2,
        spot.zone.width,
        spot.zone.height
      );
      if (Phaser.Geom.Intersects.RectangleToRectangle(playerBounds, spotBounds)) {
        this.player.hide(spot.label);
        audio.playClick();
        return;
      }
    }

    // 3. Check overlap with Interactive Objects
    for (const obj of this.interactiveZones) {
      const objBounds = new Phaser.Geom.Rectangle(
        obj.zone.x - obj.zone.width / 2,
        obj.zone.y - obj.zone.height / 2,
        obj.zone.width,
        obj.zone.height
      );
      if (Phaser.Geom.Intersects.RectangleToRectangle(playerBounds, objBounds)) {
        this.triggerInteraction(obj.data);
        return;
      }
    }
  }

