import Phaser from 'phaser';
import { ItemType, InventoryItem } from '../types';
import { audio } from '../utils/audio';

export class Player extends Phaser.GameObjects.Container {
  declare body: Phaser.Physics.Arcade.Body;
  private sprite: Phaser.GameObjects.Sprite;
  private glowGraphic: Phaser.GameObjects.Graphics;
  private shadowGraphic: Phaser.GameObjects.Graphics;

  // Stats & State
  public hearts: number = 3;
  public maxHearts: number = 3;
  public munny: number = 25; // Starting Munny
  public speed: number = 180;
  public isHidden: boolean = false;
  public hiddenSpotLabel: string = '';
  public isDisguised: boolean = false;
  public disguiseTimer: number = 0;
  public isGlowing: boolean = false;
  public glowTimer: number = 0;

  // Footstep Noise Radius
  public noiseRadius: number = 0;
  public hasQuietSlippers: boolean = false;
  private footstepTimer: number = 0;

  // Inventory Map
  public inventory: Map<ItemType, InventoryItem> = new Map();

  constructor(scene: Phaser.Scene, x: number, y: number) {
    super(scene, x, y);

    // Shadow
    this.shadowGraphic = scene.add.graphics();
    this.shadowGraphic.fillStyle(0x000000, 0.3);
    this.shadowGraphic.fillEllipse(0, 18, 36, 16);
    this.add(this.shadowGraphic);

    // Glow effect for Moisturizer
    this.glowGraphic = scene.add.graphics();
    this.glowGraphic.setVisible(false);
    this.add(this.glowGraphic);

    // Juniper Sprite
    if (scene.textures.exists('juniper')) {
      this.sprite = scene.add.sprite(0, 0, 'juniper');
      this.sprite.setDisplaySize(56, 56);
    } else {
      // Fallback procedural player drawing
      const g = scene.add.graphics();
      g.fillStyle(0x556b2f, 1); // Olive dress
      g.fillCircle(0, 4, 18);
      g.fillStyle(0x8b4513, 1); // Brown curly hair
      g.fillCircle(0, -10, 16);
      g.fillStyle(0xffdbac, 1); // Face
      g.fillCircle(0, -4, 12);
      this.sprite = scene.add.sprite(0, 0, 'juniper_fallback');
      this.add(g);
    }
    this.add(this.sprite);

    // Enable Physics
    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.body.setCircle(18, -18, -18);
    this.body.setCollideWorldBounds(true);

    // Initialize Default Inventory
    this.initInventory();
  }

  private initInventory() {
    this.inventory.set('GOLDEN_CARROT', {
      id: 'GOLDEN_CARROT',
      name: 'Golden Carrot',
      count: 3,
      icon: '🥕',
      description: 'Throw to lure Hubris away'
    });
  }

  public getItemCount(item: ItemType): number {
    return this.inventory.get(item)?.count || 0;
  }

  public addItem(item: ItemType, amount: number = 1) {
    const existing = this.inventory.get(item);
    if (existing) {
      existing.count += amount;
    } else {
      this.inventory.set(item, {
        id: item,
        name: item.replace('_', ' '),
        count: amount,
        icon: item.includes('KEY') ? '🔑' : '🎒',
        description: 'Inventory item'
      });
    }
  }

  public removeItem(item: ItemType, amount: number = 1): boolean {
    const existing = this.inventory.get(item);
    if (existing && existing.count >= amount) {
      existing.count -= amount;
      return true;
    }
    return false;
  }

  public update(delta: number, vx: number, vy: number) {
    if (this.isHidden) {
      this.body.setVelocity(0, 0);
      this.setVisible(false);
      this.noiseRadius = 0;
      return;
    }

    this.setVisible(true);

    // Movement
    const moving = vx !== 0 || vy !== 0;
    if (moving) {
      const currentSpeed = this.speed * (this.isDisguised ? 0.85 : 1.0);
      this.body.setVelocity(vx * currentSpeed, vy * currentSpeed);

      // Facing rotation
      const angle = Math.atan2(vy, vx);
      this.sprite.setRotation(angle + Math.PI / 2);

      // Noise radius calculation
      if (this.hasQuietSlippers) {
        this.noiseRadius = 0;
      } else {
        this.noiseRadius = 110;
      }

      // Footstep sound
      this.footstepTimer += delta;
      if (this.footstepTimer > 280) {
        this.footstepTimer = 0;
        audio.playFootstep();
      }
    } else {
      this.body.setVelocity(0, 0);
      this.noiseRadius = 0;
    }

    // Disguise Timer
    if (this.isDisguised) {
      this.disguiseTimer -= delta;
      if (this.disguiseTimer <= 0) {
        this.isDisguised = false;
        this.sprite.setTint(0xffffff);
      }
    }

    // Glow Timer
    if (this.isGlowing) {
      this.glowTimer -= delta;
      this.drawGlow();
      if (this.glowTimer <= 0) {
        this.isGlowing = false;
        this.glowGraphic.setVisible(false);
      }
    }
  }

  public hide(spotLabel: string) {
    this.isHidden = true;
    this.hiddenSpotLabel = spotLabel;
    this.body.setVelocity(0, 0);
  }

  public unhide() {
    this.isHidden = false;
    this.hiddenSpotLabel = '';
  }

  public activateDisguise(durationMs: number = 10000) {
    this.isDisguised = true;
    this.disguiseTimer = durationMs;
    this.sprite.setTint(0xffb6c1); // Pink tint for bunny disguise
  }

  public activateMoisturizer(durationMs: number = 4000) {
    this.isGlowing = true;
    this.glowTimer = durationMs;
    this.glowGraphic.setVisible(true);
    audio.playMoisturizerFlash();
  }

  private drawGlow() {
    this.glowGraphic.clear();
    this.glowGraphic.fillStyle(0xfff566, 0.4);
    this.glowGraphic.fillCircle(0, 0, 100);
    this.glowGraphic.lineStyle(4, 0xffd700, 0.8);
    this.glowGraphic.strokeCircle(0, 0, 100);
  }
}
