import Phaser from 'phaser';
import { audio } from '../utils/audio';

export class MenuScene extends Phaser.Scene {
  constructor() {
    super('MenuScene');
  }

  create() {
    // Backdrop Image
    if (this.textures.exists('thumbnail')) {
      const bg = this.add.image(640, 360, 'thumbnail');
      bg.setDisplaySize(1280, 720);
      bg.setAlpha(0.45);
    }

    // Title Card
    const titleText = this.add.text(640, 160, 'JUNIPER PESTO', {
      fontFamily: 'Bangers, sans-serif',
      fontSize: '72px',
      color: '#facc15',
      stroke: '#000000',
      strokeThickness: 10
    }).setOrigin(0.5);

    const subTitleText = this.add.text(640, 230, 'and the Golden Hunny House', {
      fontFamily: 'Bangers, sans-serif',
      fontSize: '44px',
      color: '#ffffff',
      stroke: '#000000',
      strokeThickness: 8
    }).setOrigin(0.5);

    // Teaser Card
    const teaserBg = this.add.graphics();
    teaserBg.fillStyle(0x000000, 0.7);
    teaserBg.fillRoundedRect(240, 280, 800, 160, 16);
    teaserBg.lineStyle(3, 0xfacc15, 0.8);
    teaserBg.strokeRoundedRect(240, 280, 800, 160, 16);

    this.add.text(640, 360, 'Trapped in a lavish golden mansion ruled by Hubris—a tiny spoiled white bunny emperor!\nSneak through 8 rooms, solve servant problems, distract guards with golden carrots, and escape!', {
      fontFamily: 'Fredoka, sans-serif',
      fontSize: '20px',
      color: '#f8fafc',
      align: 'center',
      wordWrap: { width: 760 },
      lineSpacing: 8
    }).setOrigin(0.5);

    // START GAME BUTTON
    const playBtnBg = this.add.graphics();
    playBtnBg.fillStyle(0x22c55e, 1);
    playBtnBg.fillRoundedRect(440, 480, 400, 70, 16);
    playBtnBg.lineStyle(4, 0xffffff, 1);
    playBtnBg.strokeRoundedRect(440, 480, 400, 70, 16);

    const playBtnText = this.add.text(640, 515, 'START ESCAPE ▶', {
      fontFamily: 'Bangers, sans-serif',
      fontSize: '36px',
      color: '#ffffff',
      stroke: '#000000',
      strokeThickness: 5
    }).setOrigin(0.5);

    const playZone = this.add.zone(640, 515, 400, 70).setInteractive();
    playZone.on('pointerdown', () => {
      audio.init();
      audio.playClick();
      this.scene.start('GameScene');
    });

    // Pulse animation on play button
    this.tweens.add({
      targets: [playBtnText],
      scale: 1.08,
      duration: 800,
      yoyo: true,
      repeat: -1,
      ease: 'Sine.easeInOut'
    });

    // Controls Hint
    this.add.text(640, 620, '⌨️ WASD / Arrows to Move | SPACE to Interact / Hide | 🥕 Touch On-Screen Controls for Mobile', {
      fontFamily: 'Fredoka, sans-serif',
      fontSize: '16px',
      color: '#cbd5e1'
    }).setOrigin(0.5);

    // Mute Button
    const muteBtnText = this.add.text(1220, 40, '🔊', {
      fontSize: '32px'
    }).setOrigin(0.5).setInteractive();

    muteBtnText.on('pointerdown', () => {
      audio.init();
      const muted = audio.toggleMute();
      muteBtnText.setText(muted ? '🔇' : '🔊');
    });
  }
}
