      }
    } else {
      this.body.setVelocity(0, 0);
      this.sprite.setY(0);
      this.outfitGraphic.setY(0);
      this.noiseRadius = 0;
    }

    // Disguise Timer
    if (this.isDisguised) {
      this.disguiseTimer -= delta;
      if (this.disguiseTimer <= 0) {
        this.isDisguised = false;
        this.sprite.setTint(0xffffff);
      }
    }

    // Glow Timer
    if (this.isGlowing) {
      this.glowTimer -= delta;
      this.drawGlow();
      if (this.glowTimer <= 0) {
        this.isGlowing = false;
        this.glowGraphic.setVisible(false);
      }
